const results = [];

for (const item of $input.all()) {
  // --- IMPORTANTE ---
  // Asumimos que el MIME type está en esta ruta.
  // ¡Verifica que 'item.json.data.mimetype' es correcto para tus datos!
  // Podría ser 'item.json.mimetype' o similar.
  const mimetype = $('Descargar Media').first().json.data.mimetype || '';

  let fileTypeCategory = 'other'; // Valor por defecto para tipos no reconocidos

  // Usamos switch(true) para evaluar diferentes condiciones basadas en el mimetype
  switch (true) {
    // === Imágenes ===
    case mimetype.startsWith('image/'):
      fileTypeCategory = 'image';
      break;

    // === Audio ===
    // Incluye mp3 ('audio/mpeg'), ogg, wav, etc.
    case mimetype.startsWith('audio/'):
      fileTypeCategory = 'audio';
      break;

    // === Video ===
    // Incluye mp4, webm, mov ('video/quicktime'), etc.
    case mimetype.startsWith('video/'):
      fileTypeCategory = 'video';
      break;

    // === Documentos de Texto y Ofimática ===
    case mimetype === 'application/pdf':
      fileTypeCategory = 'pdf';
      break;

    // Spreadsheets (Excel, ODS, etc.)
    case mimetype === 'application/vnd.ms-excel':
    case mimetype === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':
    case mimetype === 'application/vnd.oasis.opendocument.spreadsheet':
      fileTypeCategory = 'spreadsheet';
      break;

    // Word Documents
    case mimetype === 'application/msword':
    case mimetype === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
      fileTypeCategory = 'document';
      break;

    // Archivos de texto plano (txt, md, log)
    case mimetype === 'text/plain':
      fileTypeCategory = 'text';
      break;

    case mimetype === 'text/csv':
      fileTypeCategory = 'csv';
      break;

    case mimetype === 'text/html':
      fileTypeCategory = 'html';
      break;

    case mimetype === 'application/rtf':
      fileTypeCategory = 'rtf';
      break;

    // === Datos Estructurados ===
    case mimetype === 'application/json':
      fileTypeCategory = 'json';
      break;

    case mimetype === 'application/xml':
    case mimetype === 'text/xml':
      fileTypeCategory = 'xml';
      break;

    // === Otros ===
    case mimetype === 'text/calendar': // para .ics
      fileTypeCategory = 'ics';
      break;
  }

  // Añadimos la nueva propiedad 'fileTypeCategory' al objeto json del item
  item.json.fileTypeCategory = fileTypeCategory;

  // Añadimos el item modificado al array de resultados
  results.push(item);
}

// Devolvemos el array con todos los items modificados
return results;

const input = $input.first().json;
const type = input.type || '';
const response = input.response || '';

// Detect handoff from JSON type field
const isHandoff = type === 'handoff';

// Build clean response text for downstream nodes
const responseText = isHandoff
  ? (input.message_blocks ? input.message_blocks.join('\n') : response)
  : (input.message_blocks ? input.message_blocks.join('\n') : response);

return [{
  json: {
    ...input,
    response: responseText,
    is_handoff: isHandoff,
    handoff_reason: input.reason || '',
    message_for_handoff: isHandoff ? (input.message_blocks ? input.message_blocks[0] : response) : ''
  }
}];

const code = Math.floor(1000 + Math.random() * 9000).toString();
const number = $('Global Variables').item.json.number;
const reason = $json.handoff_reason || 'Solicitação do cliente';
const customerMsg = $json.response || 'Um momento, vou conectar você com nossa equipe! ✨';

return [{
  json: {
    code,
    number,
    reason,
    customer_message: customerMsg,
    resumo: `Handoff via bot\nNúmero: +${number}\nMotivo: ${reason}\nCódigo de retomada: ${code}`,
  }
}];

// Filter + normalize UAZAPI payload
const body = $input.first().json.body || $input.first().json;

// Only process "messages" events
const eventType = body.EventType || '';
if (eventType !== 'messages') return [];

// Get message data (UAZAPI format)
const msg = body.message || body.data || {};

// Ignore own messages
if (msg.fromMe === true) return [];

// Ignore groups
if (msg.isGroup === true) return [];

// Ignore empty messages
const text = msg.text || msg.content?.text || msg.body || '';
const msgType = (msg.type || msg.mediaType || 'text').toLowerCase();
const hasMedia = ['image', 'audio', 'video', 'document', 'sticker', 'ptt'].includes(msgType);

if (!text && !hasMedia) return [];

// Normalize and pass through with data in expected format
const chatid = msg.chatid || (msg.key && msg.key.remoteJid) || '';

return [{
  json: {
    ...($input.first().json),
    body: {
      ...body,
      data: {
        ...msg,
        key: { 
          id: msg.messageid || msg.id || '', 
          remoteJid: chatid,
          fromMe: false 
        },
        pushName: msg.senderName || body.chat?.name || 'Cliente',
        message: { conversation: text },
        messageType: msg.messageType || (hasMedia ? msgType + 'Message' : 'conversation'),
        text: text,
        body: text,
        chatid: chatid,
        messageid: msg.messageid || msg.id || ''
      }
    }
  }
}];

const rawOutput = $input.first().json.output || $input.first().json.response || '';

let parsed;
try {
  const cleaned = String(rawOutput).replace(/```json\n?|\n?```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    type: 'response',
    message_blocks: [String(rawOutput || 'Deixa eu verificar isso pra você ✨')],
    delay_seconds: 1
  };
}

if (!parsed || typeof parsed !== 'object') {
  parsed = { type: 'response', message_blocks: ['Deixa eu verificar isso pra você ✨'], delay_seconds: 1 };
}

if (!parsed.type) parsed.type = 'response';
if (!parsed.message_blocks && parsed.response) parsed.message_blocks = [parsed.response];
if (!parsed.message_blocks) parsed.message_blocks = ['Deixa eu verificar isso pra você ✨'];
if (!parsed.delay_seconds) parsed.delay_seconds = 1;

function words(value) {
  return String(value || '').trim().split(/\s+/).filter(Boolean);
}

function clean(value) {
  return String(value || '').trim();
}

function normalizeCrmContext(ctx, args = {}) {
  const source = (ctx && typeof ctx === 'object') ? ctx : {};
  const visitReason = clean(args.visit_reason || source.visit_reason || source.interesse || source.interest);
  const notes = clean(args.notes || source.summary_for_human || '');
  return {
    interesse: clean(source.interesse || source.interest || visitReason),
    material: clean(source.material),
    ocasiao: clean(source.ocasiao || source.occasion),
    orcamento: clean(source.orcamento || source.budget),
    urgencia: clean(source.urgencia || source.urgency),
    summary_for_human: clean(source.summary_for_human || notes),
    recommended_next_step: clean(source.recommended_next_step),
    visit_reason: visitReason
  };
}

function hasRealReason(args, crmContext) {
  const reason = clean(args.visit_reason || crmContext.visit_reason);
  if (words(reason).length >= 3) return true;
  const notes = clean(args.notes || crmContext.summary_for_human);
  const generic = ['observações extras', 'observacoes extras', 'agendamento', 'visita', 'atendimento', 'cliente quer agendar'];
  if (!notes || generic.includes(notes.toLowerCase())) return false;
  return words(notes).length >= 4;
}

function hasEmail(args, crmContext) {
  const email = clean(args.customer_email || args.email || crmContext.customer_email || crmContext.email);
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function hasPhoneConfirmed(args) {
  if (args.phone_confirmed === true || args.phone_confirmed === 'true') return true;
  const notes = clean(args.notes).toLowerCase();
  return /(esse|este)\s+(whatsapp|numero|número)|pode ser esse|confirmo.*(whatsapp|numero|número)/i.test(notes);
}

function sanitizeNameToken(value) {
  return clean(value).replace(/[.!?]+$/g, '');
}

function formatSingleName(value) {
  const text = sanitizeNameToken(value).toLowerCase();
  if (!text) return '';
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function greetingOpeningBlocks(message) {
  const lower = clean(message).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  let first = 'Olá, tudo bem?';
  if (/^boa\s+noite\b/.test(lower)) first = 'Olá, boa noite. Tudo bem?';
  else if (/^bom\s+dia\b/.test(lower)) first = 'Olá, bom dia. Tudo bem?';
  else if (/^boa\s+tarde\b/.test(lower)) first = 'Olá, boa tarde. Tudo bem?';
  return [
    first,
    'Aqui é a Lara, consultora virtual da ORIN Joias.',
    'Para que eu consiga te oferecer um atendimento mais preciso, você poderia me informar seu nome?'
  ];
}

function isLikelySingleName(value) {
  const text = sanitizeNameToken(value);
  const lower = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const blacklist = [
    'oi','oii','oiii','ola','olá','ok','sim','nao','não','bom','boa','dia','tarde','noite',
    'agenda','agendar','visita','alianca','aliança','anel','colar','brinco',
    'catalogo','catálogo','preco','preço','valor','horario','horário',
    'endereco','endereço','maps','mapa','loja','atendente','humano','qro','quero',
    'queria','ver','saber','obg','obrigado','obrigada','valeu','beleza','blz'
  ];
  if (/^o+i+$/.test(lower)) return false;
  if (/^ola+$/.test(lower)) return false;
  if (!/^[A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]{2,30}$/.test(text)) return false;
  return !blacklist.includes(lower) && !blacklist.includes(text.toLowerCase());
}

function responseAsk(message) {
  return [{
    json: {
      type: 'response',
      message_blocks: [message],
      delay_seconds: 1,
      crm_context: parsed.crm_context || {},
      blocked_action: parsed.action || null,
      block_reason: 'missing_required_booking_data'
    }
  }];
}

parsed.crm_context = normalizeCrmContext(parsed.crm_context || parsed.context || {});

function getOriginalUserMessage() {
  try { return String($("Get Message").first().json.message || ""); } catch(e) {}
  try { return String($items("Get Message")[0].json.message || ""); } catch(e) {}
  return "";
}

const userMessage = getOriginalUserMessage();
const msg = userMessage.trim().toLowerCase();
const looksLikeOnlyTime = /^(pode ser\s*)?(às|as)?\s*\d{1,2}(:\d{2})?\s*(h|horas)?\s*$/i.test(msg);
const hasExplicitDay = /(hoje|amanhã|amanha|depois de amanhã|segunda|terça|terca|quarta|quinta|sexta|sábado|sabado|domingo|\d{1,2}\/\d{1,2})/i.test(msg);
if (looksLikeOnlyTime && !hasExplicitDay) {
  return responseAsk("Consigo seguir com esse horário, sim. Me confirma o dia, seu nome completo e o motivo da visita?");
}

const responseText = Array.isArray(parsed.message_blocks)
  ? parsed.message_blocks.join(' ')
  : String(parsed.message_blocks || parsed.response || '');
const startsWithGreeting = /\b(oi|olá|ola|bom dia|boa tarde|boa noite)\b/i.test(msg);
const hasCommercialIntent = /(aliança|alianca|anel|colar|brinco|joia|jóia|presente|casamento|noivado|personaliza|agendar|agenda|visita|horário|horario)/i.test(msg);
const startsWithNonNamePhrase = /^(oi|olá|ola|bom\s+dia|boa\s+tarde|boa\s+noite|onde|como|qual|quero|queria|gostaria|pode|preciso|tem|voces|vocês|endereco|endereço|localizacao|localização)\b/i.test(msg);
const explicitNameAtStart = startsWithNonNamePhrase ? null : userMessage.trim().match(/^([A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+\s+[A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+)\b/);
const simpleNameOnly = isLikelySingleName(userMessage);
const userAlreadyGaveName = /\b(meu nome é|me chamo|sou a |sou o )\b/i.test(msg) || Boolean(explicitNameAtStart) || simpleNameOnly;
let contextText = '';
try { contextText = String($('Context Refiner').first().json.text || ''); } catch(e) {}
const noRelevantContext = !contextText.trim() || contextText.trim() === 'NO_CONTEXT' || contextText.trim() === '.';
const hasConfirmedNameInContext = /(nome|name|cliente|client)\s*[:\-]\s*[A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][a-záàâãéêíóôõúç]+\s+[A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][a-záàâãéêíóôõúç]+/i.test(contextText);
function getRawHistoryText() {
  const parts = [];
  try { parts.push(String($('Get chat_history').first().json.history || '')); } catch(e) {}
  try {
    const raw = $('Get chat_history1').first().json.propertyName;
    if (Array.isArray(raw)) parts.push(raw.join('\n'));
    else parts.push(String(raw || ''));
  } catch(e) {}
  try { parts.push(String($('Webhook').item.json.body?.qa_history || $('Webhook').item.json.qa_history || '')); } catch(e) {}
  return parts.filter(Boolean).join('\n');
}

function extractConfirmedCustomerName(text) {
  const source = String(text || '');
  const patterns = [
    /customer_name["']?\s*[:=]\s*["']([A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+(?:[ \t]+[A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+){0,3})["']/,
    /\b(?:Client name|Nome do cliente|Cliente|Nome)\s*[:\-]\s*([A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+(?:[ \t]+[A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+){0,3})/i,
    /\bPrazer,\s*([A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+(?:[ \t]+[A-ZÁÀÂÃÉÊÍÓÔÕÚÇ][A-Za-zÁÀÂÃÉÊÍÓÔÕÚÇáàâãéêíóôõúç]+){0,3})\b/
  ];
  const blacklist = new Set(['Cliente', 'Orin', 'Lara', 'Boa', 'Bom', 'Olá', 'Ola']);
  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (!match) continue;
    const candidate = clean(match[1]).replace(/[.!?]+$/g, '');
    const first = candidate.split(/\s+/)[0];
    if (first && !blacklist.has(first)) return candidate;
  }
  return '';
}

const rawHistoryText = getRawHistoryText();
const confirmedCustomerNameFromHistory = clean(parsed.crm_context?.customer_name || extractConfirmedCustomerName(contextText + '\n' + rawHistoryText));
const confirmedCustomerFirstName = confirmedCustomerNameFromHistory ? formatSingleName(confirmedCustomerNameFromHistory.split(/\s+/)[0]) : '';
const askedNameAgain = /(?:informar|dizer|me passa|me informe|qual (?:é|e))[^.!?\n]{0,80}\b(?:seu\s+)?nome\b|nome\?/i.test(responseText);
const appointmentIntent = /(atendimento\s+presencial|agendar|agenda|visita|horário|horario|marcar|atendimento)/i.test(msg);
const uncertaintyText = /(não entendi|nao entendi|não consegui entender|nao consegui entender|pode repetir|explique melhor|não ficou claro|nao ficou claro)/i.test(responseText);

if (confirmedCustomerNameFromHistory) {
  parsed.crm_context = { ...(parsed.crm_context || {}), customer_name: confirmedCustomerNameFromHistory };
}

if (parsed.type !== 'action' && parsed.type !== 'handoff' && confirmedCustomerNameFromHistory && appointmentIntent && askedNameAgain) {
  return [{
    json: {
      type: 'action',
      action: 'check_availability',
      pre_message_blocks: [
        `Perfeito, ${confirmedCustomerFirstName}. Vou verificar os horários disponíveis para atendimento presencial.`,
        'Aguarde um momento, por favor.'
      ],
      pre_delay_seconds: 1,
      arguments: { period: 'qualquer' },
      crm_context: {
        ...(parsed.crm_context || {}),
        customer_name: confirmedCustomerNameFromHistory,
        interesse: parsed.crm_context?.interesse || 'atendimento presencial',
        visit_reason: parsed.crm_context?.visit_reason || 'atendimento presencial'
      },
      block_reason: 'confirmed_name_from_history_appointment_guard'
    }
  }];
}

if (parsed.type !== 'action' && parsed.type !== 'handoff' && confirmedCustomerNameFromHistory && askedNameAgain) {
  return [{
    json: {
      type: 'response',
      message_blocks: [
        `Perfeito, ${confirmedCustomerFirstName}.`,
        'Me confirma só o que você prefere agora: ver o catálogo, tirar uma dúvida sobre joias ou agendar um atendimento presencial?'
      ],
      delay_seconds: 1,
      crm_context: { ...(parsed.crm_context || {}), customer_name: confirmedCustomerNameFromHistory },
      block_reason: 'do_not_ask_name_twice_guard'
    }
  }];
}

if (parsed.type !== 'action' && parsed.type !== 'handoff' && uncertaintyText) {
  return [{
    json: {
      type: 'response',
      message_blocks: [
        'Perdão, não entendi muito bem.',
        'Você quer ver nosso catálogo, tirar uma dúvida sobre joias ou agendar um atendimento presencial?'
      ],
      delay_seconds: 1,
      crm_context: parsed.crm_context || {},
      block_reason: 'low_confidence_fallback_guard'
    }
  }];
}

const rootCommand = /^\s*\//.test(msg);
const asksAddress = /(onde\s+fica|endereco|endereço|localizacao|localização|maps|mapa|local|loja)/i.test(msg);
if (parsed.type !== 'action' && parsed.type !== 'handoff' && asksAddress && !rootCommand) {
  return [{
    json: {
      type: 'response',
      message_blocks: [
        'A ORIN Joias fica na Av. Brasil, 1500 - Centro, Balneário Camboriú - SC, 88330-901.',
        'Google Maps: https://maps.app.goo.gl/geMC3hHsQqGfSnnm6',
        'Quer que eu verifique um horário para você ser atendida?'
      ],
      delay_seconds: 1,
      crm_context: parsed.crm_context || {},
      block_reason: 'address_question_guard'
    }
  }];
}
if (parsed.type !== 'action' && parsed.type !== 'handoff' && simpleNameOnly) {
  const firstName = formatSingleName(userMessage);
  return [{
    json: {
      type: 'response',
      message_blocks: [
        'Perfeito, ' + firstName + '.',
        'Me conta o que você está buscando hoje?',
        'Se quiser, posso te mostrar nosso catálogo de joias ou podemos agendar um atendimento presencial. Qual você prefere?'
      ],
      delay_seconds: 1,
      crm_context: { ...(parsed.crm_context || {}), customer_name: firstName },
      block_reason: 'single_name_detected'
    }
  }];
}
if (parsed.type !== 'action' && parsed.type !== 'handoff' && explicitNameAtStart && !hasCommercialIntent) {
  const firstName = formatSingleName(explicitNameAtStart[1].split(/\s+/)[0]);
  return [{
    json: {
      type: 'response',
      message_blocks: [
        'Perfeito, ' + firstName + '.',
        'Me conta o que você está buscando hoje?',
        'Se quiser, posso te mostrar nosso catálogo de joias ou podemos agendar um atendimento presencial. Qual você prefere?'
      ],
      delay_seconds: 1,
      crm_context: { ...(parsed.crm_context || {}), customer_name: explicitNameAtStart[1] },
      block_reason: 'full_name_detected'
    }
  }];
}
if (parsed.type !== 'handoff' && !userAlreadyGaveName && !hasConfirmedNameInContext && (noRelevantContext || hasCommercialIntent || startsWithGreeting || msg.length <= 40) && !rootCommand) {
  const blocks = greetingOpeningBlocks(userMessage);
  if (/(agendar|agenda|visita|horário|horario)/i.test(msg)) {
    blocks.push('Depois disso eu verifico os horários disponíveis para atendimento na loja.');
  } else if (/(aliança|alianca)/i.test(msg)) {
    blocks.push('Sobre alianças, posso te ajudar por aqui e encaminhar para uma especialista verificar as opções disponíveis.');
  }
  return [{
    json: {
      type: 'response',
      message_blocks: blocks,
      delay_seconds: 1,
      crm_context: parsed.crm_context || {},
      blocked_action: parsed.action || null,
      block_reason: 'missing_confirmed_customer_name'
    }
  }];
}
if (parsed.type !== 'action' && parsed.type !== 'handoff' && userAlreadyGaveName && hasCommercialIntent && explicitNameAtStart) {
  const firstName = explicitNameAtStart[1].split(/\s+/)[0];
  const blocks = ['Prazer, ' + firstName + '.'];
  if (/(aliança|alianca)/i.test(msg)) {
    blocks.push('Entendi que você quer ver alianças.');
  }
  blocks.push('Posso verificar um horário para atendimento na loja ou encaminhar para uma especialista te ajudar com as opções.');
  return [{
    json: {
      type: 'response',
