  const n = Math.max(1, Math.min(30, Number(limit) || 10));
  return `📜 *LOG ROOT* — últimas ${Math.min(n, logs.length)} alterações\n\n` + logs.slice(-n).reverse().map((x, i) => {
    const date = x.at ? new Date(x.at).toLocaleString('pt-BR') : 'sem data';
    return `${i+1}. ${date}\nAdmin: ${x.by || 'desconhecido'}\nAção: ${x.action || 'sem ação'}\nResumo: ${x.detail || '(sem detalhe)'}`;
  }).join('\n\n');
