      .replace(/ORIN Joias — Sala 316, Av\. Brasil 1500, anexo ao Hotel Sibara, Centro — Balneário Camboriú/g, 'ORIN Joias, Av. Brasil, 1500 - Centro, Balneário Camboriú - SC, 88330-901')
      .replace(/ORIN Joias, Av\. Brasil, 1500, sala 316, anexo ao Hotel Sibara, Centro, Balneário Camboriú/g, 'ORIN Joias, Av. Brasil, 1500 - Centro, Balneário Camboriú - SC, 88330-901')
      .replace(/A ORIN Joias fica na Av\. Brasil, 1500, sala 316, anexo ao Hotel Sibara, Centro, Balneário Camboriú/g, 'A ORIN Joias fica na Av. Brasil, 1500 - Centro, Balneário Camboriú - SC, 88330-901')
      .replace(/Nossa joalheria fica na Avenida Brasil, 1500, sala 316, no anexo ao Hotel Sibara, no centro de Balneário Camboriú/g, 'Nossa joalheria fica na Av. Brasil, 1500 - Centro, Balneário Camboriú - SC, 88330-901')
      .replace(/Estacionamento: R\. 101, 63[^.]*\./g, '')
      .replace(/, estacionamento/g, '')
      .replace(/estacionamento, /g, '')
      .replace(/, ponto de referência/g, '');
  }
  if (Array.isArray(value)) return value.map(sanitizeRootConfigValue);
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = sanitizeRootConfigValue(v);
    return out;
  }
  return value;
}

