}
function getRootBlock(cfg, name) {
  const key = String(name || '').trim().toUpperCase();
  const rb = mergeRootBlocks(cfg.root_blocks);
  if (key === 'BASE_LARA') return { key, value: rb.base_lara };
  if (key === 'ROUTER') return { key, value: rb.router };
  if (rb.blocks[key]) return { key, value: rb.blocks[key] };
  return null;
}
function setRootBlock(cfg, name, value) {
  const key = String(name || '').trim().toUpperCase();
  const rb = mergeRootBlocks(cfg.root_blocks);
  if (key === 'BASE_LARA') rb.base_lara = value;
  else if (key === 'ROUTER') rb.router = value;
