}

function inferRootBlockNames(blocks) {
  const msg = getCurrentUserMessageForRoot().toLowerCase();
  const selected = new Set(["IDENTIFICACAO", "DESCOBERTA", "HUMANO"]);
  if (/\b(oi|olá|ola|bom dia|boa tarde|boa noite)\b/.test(msg)) selected.add("ABERTURA");
  if (/(endereço|endereco|onde fica|localização|localizacao|maps|mapa|estacionamento)/.test(msg)) selected.add("INFORMACOES");
  if (/(catálogo|catalogo|modelo|modelos|link|site|produto|peça|peca|aliança|alianca|anel|colar|brinco)/.test(msg)) selected.add("CATALOGO");
  if (/(preço|preco|valor|quanto custa|orçamento|orcamento|pagamento|desconto|prazo)/.test(msg)) selected.add("PRECO_CONDICOES");
  if (/(personaliza|personalização|personalizacao|sob medida|gravação|gravacao|pedra|design)/.test(msg)) selected.add("PERSONALIZACAO");
  if (/(agenda|agendar|horário|horario|visita|visitar|amanhã|amanha|hoje|segunda|terça|terca|quarta|quinta|sexta|sábado|sabado|domingo|\b\d{1,2}h\b|\b\d{1,2}:\d{2}\b)/.test(msg)) selected.add("AGENDAMENTO");
  if (/(confirmado|agendado|marcado|confirmar)/.test(msg)) selected.add("POS_AGENDAMENTO");
  if (/(atendente|humano|pessoa|especialista|vendedor|consultor)/.test(msg)) selected.add("HUMANO");
