- Se o cliente iniciar com saudação + intenção, responda em blocos: acolha, pergunte o nome e comente brevemente a intenção sem pular a identificação.
`;

function shortText(value, max = 900) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  return text.length > max ? text.slice(0, max).trim() + '...' : text;
}

function tailList(arr, maxItems) {
  return (arr || []).filter(Boolean).slice(-maxItems);
}

function listShort(arr, maxItems, maxChars) {
  return tailList(arr, maxItems).map((item) => '- ' + shortText(item, maxChars)).join('\n');
}

function compactRuntimeRootSection() {
  const selectedBlocksText = (selectedBlockNames || [])
    .map((name) => '[' + name + ']\n' + shortText(rootBlocks.blocks[name], 520))
    .join('\n\n');

  const parts = [];
  parts.push('ROOT_CONFIG RUNTIME COMPACTO — fonte operacional da Lara nesta mensagem.');
