  if (config.custom_prompt) parts.push('PROMPT MASTER:\n' + shortText(config.custom_prompt, 900));
  if (config.persona_extra) parts.push('PERSONA:\n' + shortText(config.persona_extra, 500));
  if (config.tom !== undefined && config.tom !== null) parts.push('TOM:\n' + String(config.tom) + '/10.');
  if (config.objetivos?.length) parts.push('OBJETIVOS ATIVOS:\n' + listShort(config.objetivos, 6, 260));
  if (config.rules?.length) parts.push('REGRAS CRITICAS:\n' + listShort(config.rules, 8, 260));
  if (config.write_rules?.length) parts.push('REGRAS DE ESCRITA:\n' + listShort(config.write_rules, 6, 220));
  if (config.corrections?.length) parts.push('CORRECOES ATIVAS:\n' + listShort(config.corrections, 8, 220));
  if (config.links?.length) {
    parts.push('LINKS OFICIAIS:\n' + config.links.map((link) => '- ' + link.name + ': ' + link.url).join('\n'));
  }
  parts.push('ROOT_ROUTER:\n' + shortText(rootBlocks.router, 900));
  parts.push('BLOCOS SELECIONADOS:\n' + selectedBlocksText);
  parts.push('CRM_CONTEXT schema: ' + JSON.stringify(rootBlocks.crm_context_schema));
  parts.push([
    'GUARDRAILS OPERACIONAIS:',
    '- Nunca invente preço, estoque, prazo, material, política, disponibilidade ou confirmação de agenda.',
    '- Se faltar nome confirmado, pergunte o nome mesmo quando houver intenção de compra.',
    '- Primeira resposta não menciona catálogo online, site de produtos ou link direto.',
    '- Como ainda não há catálogo online oficial, não prometa link direto de produto.',
    '- Agenda real vem somente do CRM via check_availability.',
    '- create_booking só com horário escolhido, nome completo e motivo real da visita.',
    '- Ao listar horários, não envie endereço. Após create_booking bem-sucedido, envie endereço e Maps.',
    '- Responda em JSON válido no contrato técnico do Agent.',
  ].join('\n'));

  return '\n\n---\n' + parts.filter(Boolean).join('\n\n---\n');
}

const runtimeRootSection = rootSection.length > 12000 ? compactRuntimeRootSection() : rootSection;

return [{ json: { text: contextText + runtimeRootSection } }];

