const rawText   = $input.first().json.text || '';
const configRaw = $('ROOT: Ler Config Redis').item.json.propertyName || '{}';

let llmData;
try {
  const cleaned   = rawText.replace(/```json\n?|\n?```/g,'').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  llmData = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(cleaned);
} catch(e) {
  llmData = { actions:[{type:'none'}], response:'⚠️ Não entendi. Seja mais direto. Ex: "seja mais calorosa".' };
}

let config;
try { config = JSON.parse(configRaw); } catch(e) { config={}; }
config.rules         = config.rules         || [];
config.corrections   = config.corrections   || [];
config.examples      = config.examples      || [];
config.objetivos     = config.objetivos     || [];
config.persona_extra = config.persona_extra || '';
config.links         = config.links         || [];
config.audit_log     = Array.isArray(config.audit_log) ? config.audit_log : [];
config.tom           = config.tom !== undefined ? Number(config.tom) : 7;

const actions = llmData.actions || (llmData.action ? [{type:llmData.action,value:llmData.value,example_input:llmData.example_input,example_output:llmData.example_output}] : []);

const adminNumber = String($('Global Variables').item.json.number || '');
function summarizeAudit(value, max = 240) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  return text.length > max ? text.slice(0, max - 3) + '...' : text;
}
function addAudit(action, detail) {
  config.audit_log = Array.isArray(config.audit_log) ? config.audit_log : [];
  config.audit_log.push({
    at: new Date().toISOString(),
    by: adminNumber || 'desconhecido',
    action,
    detail: summarizeAudit(detail)
  });
  config.audit_log = config.audit_log.slice(-30);
}

let needsSave = false;
const applied = [];

for (const act of actions) {
  const type  = act.type  || '';
  const value = (act.value||'').trim();
  if      (type==='rule'       && value) { config.rules.push(value);             applied.push(`📋 Regra: "${value}"`);          needsSave=true; }
  else if (type==='correction' && value) { config.corrections.push(value);       applied.push(`🔧 Correção: "${value}"`);        needsSave=true; }
  else if (type==='persona'    && value) { config.persona_extra=value;            applied.push(`🎭 Personalidade: "${value}"`);   needsSave=true; }
  else if (type==='objetivo'   && value) { config.objetivos.push(value);          applied.push(`🎯 Objetivo: "${value}"`);        needsSave=true; }
  else if (type==='example'    && act.example_input) {
    config.examples.push({input:act.example_input,output:act.example_output||''});
    applied.push(`💡 "${act.example_input}" → "${act.example_output}"`);
    needsSave=true;
  } else if (type==='link' && value) {
    const p=value.split('|').map(x=>x.trim());
    if (p[0] && p[1]) {
      config.links.push({name:p[0], url:p[1], description:p[2]||''});
      applied.push(`🔗 Link: ${p[0]} — ${p[1]}`);
      needsSave=true;
    }
  } else if (type==='tom' && value) {
    const v=parseInt(value,10);
    if(!isNaN(v)&&v>=0&&v<=10) { config.tom=v; applied.push(`🎚️ Tom: ${v}/10`); needsSave=true; }
  }
}

if (needsSave) {
  config.updated_at = new Date().toISOString();
  addAudit('modo_livre', applied.join(' | '));
}

const responseText = applied.length>0
  ? `✅ ${applied.length} alteração(ões) aplicada(s):\n`+applied.join('\n')
  : llmData.response || '⚠️ Não entendi. Seja mais específico.';

return [{ json: { config, responseText, needs_save: needsSave } }];

const parsed = $input.first().json || {};

function pickQaInput() {
  const candidates = [];
  try { candidates.push($('Webhook').item.json); } catch(e) {}
  try { candidates.push($('Filter UAZAPI').item.json); } catch(e) {}
  for (const c of candidates) {
    if (!c || typeof c !== 'object') continue;
    if (c.qa_mode || c.scenario_id || c.fake_number) return c;
    if (c.body && (c.body.qa_mode || c.body.scenario_id || c.body.fake_number)) return c.body;
    if (c.data && (c.data.qa_mode || c.data.scenario_id || c.data.fake_number)) return c.data;
    if (c.body?.data && (c.body.data.qa_mode || c.body.data.scenario_id || c.body.data.fake_number)) return c.body.data;
  }
  return {};
}

const qa = pickQaInput();
const scenarioId = String(qa.scenario_id || qa.scenarioId || 'QA-UNKNOWN');
const fakeNumber = String(qa.fake_number || qa.fakeNumber || qa.number || '');

if (!fakeNumber.startsWith('+550000000') && !fakeNumber.startsWith('550000000')) {
  return [{ json: {
    scenario_id: scenarioId,
    type: 'qa_error',
    side_effects_blocked: true,
    error: 'qa_mode requer fake_number com prefixo +550000000',
    original_output: parsed
  }}];
}

const action = parsed.action || parsed.action_type || null;
let mocked_tool_result = null;
if (parsed.type === 'action' && action === 'check_availability') {
  mocked_tool_result = {
    success: true,
    qa_mock: true,
    slots: [
      '2026-07-01T09:00:00-03:00',
      '2026-07-01T10:00:00-03:00',
      '2026-07-01T11:00:00-03:00'
    ]
  };
}
if (parsed.type === 'action' && action === 'create_booking') {
  mocked_tool_result = {
    success: true,
    qa_mock: true,
    appointment_id: 'QA-MOCK-APPOINTMENT',
    message: 'Appointment simulado. Nenhum CRM real foi alterado.'
  };
}
if (parsed.type === 'handoff' || action === 'handoff') {
  mocked_tool_result = {
    success: true,
    qa_mock: true,
    handoff_id: 'QA-MOCK-HANDOFF'
  };
}

return [{ json: {
  scenario_id: scenarioId,
  qa_mode: true,
  fake_number: fakeNumber,
  side_effects_blocked: true,
  type: parsed.type || 'response',
  action,
  message_blocks: Array.isArray(parsed.message_blocks) ? parsed.message_blocks : [],
  action_args: parsed.action_args || {},
  crm_context: parsed.crm_context || parsed.action_args?.crm_context || {},
  mocked_tool_result,
  original_output: parsed
}}];
